mapper.select:
SELECT  COUNT(checkin) AS work_day,
ROUND(
    COALESCE(
        SUM(TIME_TO_SEC(TIMEDIFF(checkout, checkin)) / 3600),
        0
    ),
    1
) AS total_work_time,
ROUND(
    COALESCE(
        SUM(
            GREATEST( 
                TIME_TO_SEC(TIMEDIFF(checkout, checkin)) / 3600 - 9,
                0
            )
        ),
        0
    ),
    1
) AS overtime
FROM ta
WHERE sabun = #{sabun}
AND checkin IS NOT NULL
AND checkout IS NOT NULL
AND YEAR(day) = YEAR(NOW())
AND MONTH(day) = MONTH(NOW());
